const bill = { id: 1, amountKobo: 45000000, paidKobo: 0 };
const pending = [];

async function reserve(billId, amount) {
  const held = pending.filter((p) => p.billId === billId).reduce((sum, p) => sum + p.amount, 0);
  if (amount > bill.amountKobo - bill.paidKobo - held) throw new Error("too much");
  pending.push({ billId, amount });
}

const results = await Promise.allSettled([reserve(1, 45000000), reserve(1, 45000000)]);
console.log(results.map((r) => r.status).join(" "), pending.length);

