const failures = new Map();
function attempt(account, passwordOk) {
  const key = account.toLowerCase();
  if ((failures.get(key) ?? 0) >= 3) return 429;
  if (!passwordOk) {
    failures.set(key, (failures.get(key) ?? 0) + 1);
    return 401;
  }
  failures.delete(key);
  return 201;
}

const out = [];
for (const ok of [false, false, true, false, false, false, true]) out.push(attempt("greenfield/Ada@Example.com", ok));
out.push(attempt("greenfield/kemi@example.com", true));
console.log(out.join(" "));
